//! C/Rust differential: BIND+PARAMS sequence generated by NFQUEUE open.

use r2o_datapath::netlink::{NFQNL_CFG_CMD_BIND, config_command, config_params};

fn print_hex(name: &str, bytes: &[u8]) {
    print!("{name} len={} hex=", bytes.len());
    for byte in bytes {
        print!("{byte:02x}");
    }
    println!();
}

fn run(prefix: &str, fail_open: bool) {
    let bind = config_command(4242, 1, NFQNL_CFG_CMD_BIND, libc::AF_INET as u16);
    print_hex(&format!("{prefix}-bind"), &bind);
    let params = config_params(4242, 2, 65535, 1024, fail_open);
    print_hex(&format!("{prefix}-params"), &params);
}

fn main() {
    run("open", true);
    run("no-fail-open", false);
}
